import { languageSelector } from "~/renderer/reducers/settings";

const LEDGER_COM_ROOT = "https://www.ledger.com/";
const SUPPORT_LEDGER_COM_ROOT = "https://support.ledger.com/hc/";
const SHOP_LEDGER_COM_ROOT = "https://shop.ledger.com/";

// Locale overrides for the different Ledger web properties. When a locale is
// not listed the raw locale code is used as-is.
const ledgerComLocales: Record<string, string> = {
  pt: "pt-br",
  zh: "zh-hans",
};

const supportLedgerComLocales: Record<string, string> = {
  fr: "fr-fr",
  en: "en-us",
  zh: "zh-cn",
};

const shopLedgerComLocales: Record<string, string> = {
  pt: "pt-br",
};

/**
 * Localizes URLs pointing to Ledger's web properties based on the language
 * currently selected in the app.
 *
 * - `www.ledger.com`: the locale is inserted right after the domain root.
 * - `support.ledger.com`: the locale is inserted between `/hc/` and the path.
 * - `shop.ledger.com`: the locale is inserted right after the domain root.
 *
 * Any other domain is returned unchanged.
 */
export function useLocalizedUrl(url: string): string {
  const locale = useSelector(languageSelector);

  if (url.startsWith(LEDGER_COM_ROOT)) {
    const localized = ledgerComLocales[locale] ?? locale;
    return url.replace(LEDGER_COM_ROOT, `${LEDGER_COM_ROOT}${localized}/`);
  }

  if (url.startsWith(SUPPORT_LEDGER_COM_ROOT)) {
    const localized = supportLedgerComLocales[locale] ?? locale;
    return url.replace(SUPPORT_LEDGER_COM_ROOT, `${SUPPORT_LEDGER_COM_ROOT}${localized}/`);
  }

  if (url.startsWith(SHOP_LEDGER_COM_ROOT)) {
    const localized = shopLedgerComLocales[locale] ?? locale;
    return url.replace(SHOP_LEDGER_COM_ROOT, `${SHOP_LEDGER_COM_ROOT}${localized}/`);
  }

